<?php
session_start();
require __DIR__.'/config.php';
function h($v): string { return htmlspecialchars((string)($v ?? ''), ENT_QUOTES, 'UTF-8'); }
function go(string $page, string $msg=''): never { header('Location: index.php?page='.urlencode($page).($msg ? '&msg='.urlencode($msg) : '')); exit; }
function all(string $table): array { return db()->query("SELECT * FROM $table ORDER BY id DESC")->fetchAll(); }
function one(string $table, int $id): ?array { $s=db()->prepare("SELECT * FROM $table WHERE id=?"); $s->execute([$id]); return $s->fetch() ?: null; }
$tables=['produtos'=>['nome','descricao','peso','valor'],'enderecos'=>['identificacao','rua','numero','cidade','estado','cep'],'transportadores'=>['nome','documento','telefone','veiculo']];
$labels=['produtos'=>'Produtos','enderecos'=>'Endereços','transportadores'=>'Transportadores','fretes'=>'Fretes','relatorio'=>'Relatório'];
$fields=['nome'=>'Nome','descricao'=>'Descrição','peso'=>'Peso (kg)','valor'=>'Valor (R$)','identificacao'=>'Identificação do local','rua'=>'Rua','numero'=>'Número','cidade'=>'Cidade','estado'=>'UF','cep'=>'CEP','documento'=>'CPF/CNPJ','telefone'=>'Telefone','veiculo'=>'Veículo'];
$page=$_GET['page']??'inicio';
if (!in_array($page,array_merge(['inicio','fretes','relatorio'],array_keys($tables)),true)) $page='inicio';
$error='';
try {
    if ($_SERVER['REQUEST_METHOD']==='POST') {
        if (!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')) throw new RuntimeException('Sessão expirada. Atualize a página.');
        $action=$_POST['action']??'';
        if ($action==='save' && isset($tables[$page])) {
            $columns=$tables[$page]; $data=[];
            foreach ($columns as $field) $data[$field]=trim((string)($_POST[$field]??''));
            foreach (['nome','identificacao','rua','numero','cidade','estado','cep'] as $required) if (array_key_exists($required,$data) && $data[$required]==='') throw new RuntimeException('Preencha o campo obrigatório: '.$fields[$required]);
            foreach (['peso','valor'] as $numeric) if (isset($data[$numeric]) && (!is_numeric($data[$numeric]) || (float)$data[$numeric]<0)) throw new RuntimeException('Informe um número válido em '.$fields[$numeric]);
            $id=(int)($_POST['id']??0);
            if ($id) { $sql='UPDATE '.$page.' SET '.implode(', ',array_map(fn($f)=>"$f=?",$columns)).' WHERE id=?'; $values=array_values($data);$values[]=$id; }
            else { $sql='INSERT INTO '.$page.' ('.implode(',',$columns).') VALUES ('.implode(',',array_fill(0,count($columns),'?')).')';$values=array_values($data); }
            $s=db()->prepare($sql);$s->execute($values);go($page,'Registro salvo com sucesso.');
        }
        if ($action==='frete') {
            $transportador=(int)($_POST['transportador_id']??0);$origem=(int)($_POST['origem_id']??0);$destino=(int)($_POST['destino_id']??0);
            $date=$_POST['data_frete']??''; $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
            if (!$transportador || !$origem || !$destino || $origem===$destino || !$dt || $dt->format('Y-m-d')!==$date) throw new RuntimeException('Informe transportador, endereços diferentes e uma data válida.');
            $ids=$_POST['produto_id']??[]; $qty=$_POST['quantidade']??[]; $items=[];
            foreach ($ids as $i=>$pid) { $pid=(int)$pid;$q=(int)($qty[$i]??0);if($pid>0 && $q>0) $items[$pid]=($items[$pid]??0)+$q; }
            if (!$items) throw new RuntimeException('Selecione ao menos um produto com quantidade positiva.');
            db()->beginTransaction();
            try {
                $s=db()->prepare('INSERT INTO fretes (transportador_id,origem_id,destino_id,data_frete,observacoes) VALUES (?,?,?,?,?)');
                $s->execute([$transportador,$origem,$destino,$date,trim((string)($_POST['observacoes']??''))]);
                $freteId=(int)db()->lastInsertId();$s=db()->prepare('INSERT INTO frete_produtos (frete_id,produto_id,quantidade) VALUES (?,?,?)');
                foreach ($items as $pid=>$q) $s->execute([$freteId,$pid,$q]);
                db()->commit();go('fretes','Frete #'.$freteId.' gerado com sucesso.');
            } catch(Throwable $e) {db()->rollBack();throw $e;}
        }
        throw new RuntimeException('Operação inválida.');
    }
    if ($page==='relatorio' && ($_GET['download']??'')==='csv') {
        $date=$_GET['data']??''; $dt=DateTimeImmutable::createFromFormat('!Y-m-d',$date);
        if (!$dt || $dt->format('Y-m-d')!==$date) throw new RuntimeException('Selecione uma data válida.');
        $s=db()->prepare('SELECT f.id,f.data_frete,t.nome transportador,eo.identificacao origem,ed.identificacao destino,p.nome produto,fp.quantidade FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id WHERE f.data_frete=? ORDER BY f.id,p.nome');$s->execute([$date]);
        header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="fretes-'.$date.'.csv"');
        $out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['Frete','Data','Transportador','Origem','Destino','Produto','Quantidade'],';');foreach($s as $row)fputcsv($out,$row,';');fclose($out);exit;
    }
    $pdo=db();
} catch(Throwable $e) { $error=$e instanceof PDOException ? 'Erro de banco de dados. Confira a configuração, os registros e as dependências.' : $e->getMessage(); }
$_SESSION['csrf']??=bin2hex(random_bytes(24));
$csrf=$_SESSION['csrf'];
$editing=isset($tables[$page]) && isset($_GET['edit']) && !$error ? one($page,(int)$_GET['edit']) : null;
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>RotaFácil | Gerenciador Logístico</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="assets/style.css"></head><body>
<nav class="navbar navbar-expand-lg navbar-dark bg-primary"><div class="container"><a class="navbar-brand fw-bold" href="index.php">🚚 RotaFácil</a><button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#menu"><span class="navbar-toggler-icon"></span></button><div class="collapse navbar-collapse" id="menu"><div class="navbar-nav ms-auto"><?php foreach ($labels as $key=>$label): ?><a class="nav-link <?= $page===$key?'active':'' ?>" href="?page=<?=h($key)?>"><?=h($label)?></a><?php endforeach; ?></div></div></div></nav>
<main class="container py-4"><div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h1 class="h3 fw-bold mb-1"><?=h($page==='inicio'?'Painel de controle':$labels[$page])?></h1><p class="text-secondary mb-0">Gerenciamento simples de produtos, rotas e entregas.</p></div><span class="badge text-bg-light border">Projeto acadêmico • PHP + MySQL</span></div>
<?php if ($error): ?><div class="alert alert-danger"><?=h($error)?></div><?php endif; ?>
<?php if(isset($_GET['msg'])): ?><div class="alert alert-success"><?=h($_GET['msg'])?></div><?php endif; ?>
<?php if($page==='inicio'): ?><div class="row g-3 mb-4"><?php foreach (['produtos','enderecos','transportadores','fretes'] as $t): ?><div class="col-md-3"><div class="card h-100 shadow-sm"><div class="card-body"><div class="text-secondary small"><?=h($labels[$t])?></div><div class="display-6 fw-bold"><?php try {echo (int)db()->query('SELECT COUNT(*) FROM '.$t)->fetchColumn();}catch(Throwable $e){echo '—';}?></div><a href="?page=<?=h($t)?>" class="stretched-link">Gerenciar</a></div></div></div><?php endforeach; ?></div><div class="card"><div class="card-body"><h2 class="h5">Como começar</h2><p class="mb-0">Cadastre os produtos, dois endereços e um transportador. Depois, acesse <strong>Fretes</strong> para vincular vários produtos a uma entrega. Use <strong>Relatório</strong> para exportar os fretes por data.</p></div></div>
<?php elseif(isset($tables[$page])): ?><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5"><?= $editing?'Editar registro':'Novo cadastro' ?></h2><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=h($editing['id']??0)?>"><?php foreach($tables[$page] as $f): ?><div class="col-md-<?=in_array($f,['descricao','rua','nome','identificacao'])?6:3?>"><label class="form-label" for="f_<?=h($f)?>"><?=h($fields[$f])?></label><input class="form-control" id="f_<?=h($f)?>" name="<?=h($f)?>" value="<?=h($editing[$f]??'')?>" <?=in_array($f,['peso','valor'])?'type="number" min="0" step="0.01"':'type="text"'?> <?=in_array($f,['nome','identificacao','rua','numero','cidade','estado','cep'])?'required':''?>></div><?php endforeach; ?><div class="col-12"><button class="btn btn-primary" type="submit">Salvar</button><?php if($editing): ?><a class="btn btn-outline-secondary" href="?page=<?=h($page)?>">Cancelar</a><?php endif; ?></div></form></div></div><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Registros cadastrados</h2><div class="table-responsive"><table class="table table-hover align-middle"><thead><tr><th>ID</th><?php foreach($tables[$page] as $f): ?><th><?=h($fields[$f])?></th><?php endforeach; ?><th>Ação</th></tr></thead><tbody><?php try {foreach(all($page) as $r): ?><tr><td><?=h($r['id'])?></td><?php foreach($tables[$page] as $f): ?><td><?=h($r[$f])?></td><?php endforeach; ?><td><a class="btn btn-sm btn-outline-primary" href="?page=<?=h($page)?>&edit=<?=h($r['id'])?>">Editar</a></td></tr><?php endforeach;}catch(Throwable $e){} ?></tbody></table></div></div></div>
<?php elseif($page==='fretes'): ?><?php $products=all('produtos');$addresses=all('enderecos');$carriers=all('transportadores'); ?><div class="card shadow-sm mb-4"><div class="card-body"><h2 class="h5">Gerar novo frete</h2><?php if(!$products || count($addresses)<2 || !$carriers): ?><div class="alert alert-warning">Cadastre ao menos um produto, dois endereços e um transportador antes de criar um frete.</div><?php endif; ?><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=h($csrf)?>"><input type="hidden" name="action" value="frete"><div class="col-md-6"><label class="form-label">Transportador</label><select class="form-select" name="transportador_id" required><option value="">Selecione</option><?php foreach($carriers as $r): ?><option value="<?=h($r['id'])?>"><?=h($r['nome'])?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Data do frete</label><input class="form-control" type="date" name="data_frete" value="<?=date('Y-m-d')?>" required></div><?php foreach(['origem_id'=>'Origem','destino_id'=>'Destino'] as $key=>$label): ?><div class="col-md-6"><label class="form-label"><?=h($label)?></label><select class="form-select" name="<?=h($key)?>" required><option value="">Selecione</option><?php foreach($addresses as $r): ?><option value="<?=h($r['id'])?>"><?=h($r['identificacao'].' — '.$r['cidade'].'/'.$r['estado'])?></option><?php endforeach; ?></select></div><?php endforeach; ?><div class="col-12"><label class="form-label">Produtos transportados</label><div id="itens"><div class="row g-2 mb-2 item-frete"><div class="col-8"><select class="form-select" name="produto_id[]" required><option value="">Selecione um produto</option><?php foreach($products as $r): ?><option value="<?=h($r['id'])?>"><?=h($r['nome'])?></option><?php endforeach; ?></select></div><div class="col-3"><input class="form-control" type="number" min="1" name="quantidade[]" value="1" required aria-label="Quantidade"></div><div class="col-1"><button type="button" class="btn btn-outline-danger remover" aria-label="Remover produto">×</button></div></div></div><button type="button" id="adicionar" class="btn btn-outline-primary btn-sm">+ Adicionar produto</button></div><div class="col-12"><label class="form-label">Observações</label><textarea class="form-control" name="observacoes" rows="2"></textarea></div><div class="col-12"><button class="btn btn-primary" <?=(!$products || count($addresses)<2 || !$carriers)?'disabled':''?>>Gerar frete</button></div></form></div></div><div class="card"><div class="card-body"><h2 class="h5">Fretes cadastrados</h2><div class="table-responsive"><table class="table"><thead><tr><th>Nº</th><th>Data</th><th>Transportador</th><th>Origem</th><th>Destino</th><th>Produtos</th></tr></thead><tbody><?php $sql='SELECT f.id,f.data_frete,t.nome transportador,eo.identificacao origem,ed.identificacao destino, GROUP_CONCAT(CONCAT(p.nome," (",fp.quantidade,")") SEPARATOR ", ") produtos FROM fretes f JOIN transportadores t ON t.id=f.transportador_id JOIN enderecos eo ON eo.id=f.origem_id JOIN enderecos ed ON ed.id=f.destino_id JOIN frete_produtos fp ON fp.frete_id=f.id JOIN produtos p ON p.id=fp.produto_id GROUP BY f.id,f.data_frete,t.nome,eo.identificacao,ed.identificacao ORDER BY f.id DESC';foreach(db()->query($sql) as $r): ?><tr><?php foreach($r as $v): ?><td><?=h($v)?></td><?php endforeach; ?></tr><?php endforeach; ?></tbody></table></div></div></div>
<?php elseif($page==='relatorio'): ?><div class="card shadow-sm"><div class="card-body"><h2 class="h5">Relatório diário de fretes</h2><p>Escolha a data para baixar um arquivo CSV, que pode ser aberto no Excel.</p><form method="get" class="row g-3 align-items-end"><input type="hidden" name="page" value="relatorio"><input type="hidden" name="download" value="csv"><div class="col-md-5"><label class="form-label">Data</label><input type="date" name="data" class="form-control" value="<?=date('Y-m-d')?>" required></div><div class="col-md-4"><button class="btn btn-primary">Baixar relatório CSV</button></div></form></div></div><?php endif; ?></main><footer class="container py-4 text-secondary small">Projeto acadêmico • Higor Daniel Pereira de Andrade • ADS</footer><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="assets/app.js"></script></body></html>
